from urllib.parse import urlparse

def preview(url, approved_fetcher):
    parsed = urlparse(url)
    if parsed.scheme != 'https' or parsed.hostname not in {'assets.example.test'}:
        raise ValueError('unapproved destination')
    return approved_fetcher.fetch(parsed.geturl(), block_private_networks=True)
